import{_ as i}from"./chunks/failure-clustering-fingerprint.B8ggWE9V.js";import{_ as l}from"./chunks/failure-clusters-tab.CzmMvvxd.js";import{_ as d,C as t,o as h,c,j as s,a as u,E as r,a6 as a}from"./chunks/framework.CCKCzdWs.js";const _=JSON.parse('{"title":"Failure clusters & the inbox","description":"Failures that share an error fingerprint grouped into one cluster, triaged once from the failure inbox with an owner, a known issue and snoozing.","frontmatter":{"title":"Failure clusters & the inbox","description":"Failures that share an error fingerprint grouped into one cluster, triaged once from the failure inbox with an owner, a known issue and snoozing.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/failure-clusters.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/failure-clusters.html"}],["meta",{"property":"og:title","content":"Failure clusters & the inbox | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Failures that share an error fingerprint grouped into one cluster, triaged once from the failure inbox with an owner, a known issue and snoozing."}]]},"headers":[],"relativePath":"features/failure-clusters.md","filePath":"features/failure-clusters.md","lastUpdated":1794004811000}'),g={name:"features/failure-clusters.md"};function f(p,e,m,b,w,x){const o=t("Needs"),n=t("DemoExamples");return h(),c("div",null,[e[0]||(e[0]=s("h1",{id:"failure-clusters-the-inbox",tabindex:"-1"},[u("Failure clusters & the inbox "),s("a",{class:"header-anchor",href:"#failure-clusters-the-inbox","aria-label":'Permalink to "Failure clusters & the inbox"'},"​")],-1)),r(o,{reporter:""}),e[1]||(e[1]=a('<p>One root cause usually breaks several tests, run after run. Piwi groups failures by root cause into <strong>failure clusters</strong>, and Home turns them into a <strong>failure inbox</strong>: the problems you still owe a decision.</p><h2 id="how-failures-are-grouped" tabindex="-1">How failures are grouped <a class="header-anchor" href="#how-failures-are-grouped" aria-label="Permalink to &quot;How failures are grouped&quot;">​</a></h2><p>Failed executions sharing an <strong>error fingerprint</strong> join one cluster, so twenty stack traces read as <em>&quot;20 failures, 3 root causes&quot;</em>. Clustering is always on.</p><ul><li>The fingerprint <strong>masks volatile fragments</strong> of the error (<a href="/guide/concepts.html#error-fingerprint-failure-cluster">the list</a>): numbers, ids, timestamps, machine paths, an assertion&#39;s <em>expected</em> and <em>received</em> values, a table row&#39;s <code>{ name: &#39;…&#39; }</code>. The locator target itself (the test id, the role) still tells different failures apart.</li><li>It is <strong>call-site agnostic</strong> when the error says what failed: one root cause reached from several spec files stays one cluster. A <strong>generic</strong> error (a bare <code>toBe</code>, a test timeout, a <code>TypeError</code>) is told apart by the file it failed in.</li><li>The fingerprint is computed from the error the cluster was created from, so an improved normalization regroups clusters in place and keeps their triage, notes, diagnoses and merges.</li><li>A run&#39;s <strong>Tests</strong> tab can group its failures by cluster, each group with its triage status; the <code>get_failure_groups</code> <a href="/reference/mcp-tools.html#get_failure_groups">MCP tool</a> adds a <strong>worker-correlation</strong> flag: &quot;the app is broken&quot; versus &quot;worker 3 is misbehaving&quot;.</li></ul><figure><img src="'+i+'" alt="The fingerprint pipeline: a raw error is normalized, hashed and routed to one cluster"></figure><p>With an embedding model configured, near-duplicate clusters that the fingerprint keeps apart are merged too: see <a href="./ai-diagnosis.html#semantic-merging-optional">semantic merging</a>.</p><figure><img src="'+l+'" alt="A project&#39;s Failures tab: its open clusters with type, triage, tests and occurrences"><figcaption>A project&#39;s open clusters, one row per root cause.</figcaption></figure><h2 id="the-failure-inbox" tabindex="-1">The failure inbox <a class="header-anchor" href="#the-failure-inbox" aria-label="Permalink to &quot;The failure inbox&quot;">​</a></h2><p>The <strong>Failure inbox</strong> on Home lists up to 50 open failure clusters across the projects you can see, most recently seen first. Each row shows the cluster&#39;s <strong>headline</strong>, <strong>top clue</strong>, <strong>owner or assignee</strong>, <strong>affected-test count</strong>, when it was <strong>last seen</strong>, and only the exceptional <strong>badges</strong>, such as a regression on the default branch. A cluster seen in developers&#39; local runs and never in CI, in a project that runs in CI, stays out: the inbox says how many, and <strong>Show them</strong> lists them.</p><h3 id="queues" tabindex="-1">Queues <a class="header-anchor" href="#queues" aria-label="Permalink to &quot;Queues&quot;">​</a></h3><p>The inbox has queues, each with a live count, shareable in the URL as <code>?queue=</code>.</p><table tabindex="0"><thead><tr><th>Queue</th><th>What it holds</th></tr></thead><tbody><tr><td><strong>All open</strong></td><td>Every open, non-snoozed cluster.</td></tr><tr><td><strong>New</strong></td><td>Clusters first seen, or seen again, since your previous browser session (kept per browser).</td></tr><tr><td><strong>Mine</strong></td><td>Clusters whose assignee, or <code>piwi:owner</code> annotation, is you.</td></tr><tr><td><strong>Needs ticket</strong></td><td>Untracked default-branch clusters older than 2 days, by default; see <a href="./issue-tracking.html">issue tracking</a>.</td></tr><tr><td><strong>Regressions</strong></td><td>Clusters that regressed on the default branch and are still failing there.</td></tr><tr><td><strong>Fix didn&#39;t hold</strong></td><td>Clusters whose fix landed then regressed.</td></tr><tr><td><strong>Quarantine ready</strong></td><td>Quarantined clusters whose tests stopped failing.</td></tr><tr><td><strong>Merge suggestions</strong></td><td>Clusters in a pending merge suggestion (see <a href="./ai-diagnosis.html#semantic-merging-optional">semantic merging</a>).</td></tr></tbody></table><h3 id="triage-from-the-row-or-the-keyboard" tabindex="-1">Triage from the row or the keyboard <a class="header-anchor" href="#triage-from-the-row-or-the-keyboard" aria-label="Permalink to &quot;Triage from the row or the keyboard&quot;">​</a></h3><p>Every row can be triaged in place. Select a row with the mouse or <code>j</code> / <code>k</code>, then: <code>o</code> open, <code>r</code> resolve, <code>i</code> ignore, <code>q</code> quarantine the cluster&#39;s tests, <code>a</code> assign, <code>s</code> snooze, <code>l</code> link a known issue, <code>c</code> create a Jira issue (when a tracker is connected). <code>x</code> selects rows for a <strong>bulk bar</strong> that applies the same actions to all of them. Resolve, ignore, snooze and assign on one row can be undone for a few seconds. <a href="/reference/keyboard-shortcuts.html#failure-inbox">Keyboard shortcuts</a> lists every key.</p><p>Linking a known issue (<code>l</code>) pins a URL; with the project bound to an <a href="/operate/integrations.html">issue tracker</a>, Jira links to its site unfurl and stay in sync (see <a href="/features/issue-tracking.html">issue tracking</a>).</p><h2 id="owners-and-assignees" tabindex="-1">Owners and assignees <a class="header-anchor" href="#owners-and-assignees" aria-label="Permalink to &quot;Owners and assignees&quot;">​</a></h2><p>A cluster&#39;s <strong>owner</strong> is derived, not stored: it comes from the failing test&#39;s <code>piwi:owner</code> annotation; the cluster and execution pages (not the inbox) fall back to the repository&#39;s <code>CODEOWNERS</code>. An <strong>assignee</strong> overrides it, and the <strong>Mine</strong> queue matches either against the signed-in user (by name, username or email).</p><h2 id="the-cluster-page" tabindex="-1">The cluster page <a class="header-anchor" href="#the-cluster-page" aria-label="Permalink to &quot;The cluster page&quot;">​</a></h2><p>A cluster page leads with a failing execution&#39;s situation block (<a href="/guide/first-failure.html">Your first failure</a>), across every test sharing the failure. The heading is the latest failure&#39;s headline when it says more (a timeout, a count) than the cluster&#39;s name, which sits under it. Three lines are cluster-specific:</p><ul><li><strong>The state line</strong>, right above <strong>Next</strong>.</li><li><strong>The occurrence sparkline</strong>: how often it failed across recent runs, <em>N occurrences in M tests over D · last X ago</em>; a single test is named, <em>quarantined</em> if it is.</li><li><strong>What changed</strong>: the commits and files since the last passing run (or your baseline), with <strong>See the changes</strong> for the diff and, with <a href="./server-coverage.html">coverage</a>, the first <a href="/guide/concepts.html#suspect-lines">suspect line</a>: a changed line the failing tests ran, marked in the diff. Missing setup (no commit or repository URL, an unsupported host, a missing or refused <a href="/guide/source-control.html">SCM token</a>) shows the range, the host&#39;s error, its <strong>Compare</strong> page and a hint on what to set up; <strong>More actions › Copy git log</strong> lists the range in your checkout. With no passing run yet, <strong>Browse commits</strong> picks a baseline. The same commit on both sides means the change is not in the code.</li></ul><p>With several tests, the <strong>Affected tests</strong> list picks the one the evidence shows; <strong>Move to a new cluster</strong><a href="./ai-diagnosis.html#split-a-cluster-by-hand">splits tests off</a>. The fix section <strong>Next</strong> points at leads under the block; the rest fold into <a href="./fix-plans.html#more-ways-to-fix"><strong>More ways to fix</strong></a>.</p><h3 id="the-state-line" tabindex="-1">The state line <a class="header-anchor" href="#the-state-line" aria-label="Permalink to &quot;The state line&quot;">​</a></h3><p>The cluster page states where a cluster stands in <strong>one sentence with one verb</strong>, next to a colored dot: <em>still failing</em>, <em>not seen for N runs</em>, <em>fixed and verified, still open</em>, <em>fixed, but the diagnosed patch still applies</em>, <em>stopped failing</em>, <em>regressed, the fix did not hold</em>, <em>resolved</em>, <em>ignored</em>, <em>snoozed</em> or <em>all tests quarantined</em>. When an open cluster stopped failing, or its ticket is Done and the failure <a href="/guide/concepts.html#cluster-state">stopped</a>, the page offers <strong>one action</strong>, <em>Mark resolved</em>, which a fix whose patch still applies keeps in the <strong>Next</strong> menu; a snoozed cluster offers <em>Unsnooze</em>, an all-quarantined one <em>Release</em>. Beside it, <strong>Triage</strong> sets the status (open / resolved / ignored), a note and the assignee, and <a href="#snoozing">snoozes</a> the cluster. A status change keeps the triage note and the lines Piwi added, a note edit the status.</p><h3 id="occurrences-over-time" tabindex="-1">Occurrences over time <a class="header-anchor" href="#occurrences-over-time" aria-label="Permalink to &quot;Occurrences over time&quot;">​</a></h3><p>Folded under the fixes, a chart counts failures per day, week or month since first seen, marking the <strong>fix landed</strong>; the sparkline opens it.</p><h2 id="did-the-fix-work" tabindex="-1">Did the fix work? <a class="header-anchor" href="#did-the-fix-work" aria-label="Permalink to &quot;Did the fix work?&quot;">​</a></h2><p>When a run executes every test a cluster covers and they all pass, Piwi records the fix: the run, the commit, and how long the cluster was open. Three verdicts:</p><table tabindex="0"><thead><tr><th>Verdict</th><th>Means</th></tr></thead><tbody><tr><td><strong>Stopped failing</strong></td><td>The tests pass again. A flaky test can achieve this by accident.</td></tr><tr><td><strong>Diagnosis verified</strong></td><td>The commits since the last failing run touched a file the <a href="./ai-diagnosis.html#what-a-diagnosis-contains">suggested patch</a> named.</td></tr><tr><td><strong>Regressed</strong></td><td>A fix was recorded, and the cluster is failing again.</td></tr></tbody></table><p><strong>A fix needs every affected test to pass</strong> in the Playwright projects it last failed in (<a href="/guide/concepts.html#cluster-state">still configured</a>) that the run ran (a <code>--grep</code> over the affected tests is enough) in a run that could carry one: started after the last failing run, at another commit (a pass at the failing commit, such as a CI retry, is flake evidence, and the state line says so), on the branch the cluster last failed on or the default branch, so a green pull-request branch leaves a cluster failing on <code>main</code> open.</p><p><strong>A regression needs a run started after the fix landed</strong>, failing on the fix&#39;s branch or the default branch.</p><p>The verdict moves the status only on strong evidence: <em>Diagnosis verified</em> sets an <strong>open</strong> cluster <strong>resolved</strong>, and <em>Regressed</em> sets a <strong>resolved</strong> one back to <strong>open</strong>, as does a new failure after a person resolved a cluster with no fix on record; each adds a line to the triage note. <em>Stopped failing</em> alone changes nothing, and an <em>ignored</em> cluster is never touched. The <a href="./notifications.html">notifications</a> <code>cluster.fixed</code> and <code>cluster.regressed</code> follow the verdict, and with <a href="./pr-feedback.html">pull-request feedback</a> on, the comment gains a <strong>Fixed by this change</strong> section, even with <em>only comment on failures</em> set.</p><h2 id="snoozing" tabindex="-1">Snoozing <a class="header-anchor" href="#snoozing" aria-label="Permalink to &quot;Snoozing&quot;">​</a></h2><p><strong>Snoozing</strong> hides a cluster from every inbox queue without touching its status. <strong>1 day</strong> and <strong>1 week</strong> return it then; <strong>Until it recurs</strong> returns it to the <strong>New</strong> queue when a new run fails it again, with a <strong>snoozed, back</strong> badge until your next visit.</p><h2 id="from-an-ai-agent" tabindex="-1">From an AI agent <a class="header-anchor" href="#from-an-ai-agent" aria-label="Permalink to &quot;From an AI agent&quot;">​</a></h2><p>Over the <a href="/features/mcp.html">MCP server</a>, <code>list_open_clusters</code> takes the same <code>queue</code> argument, and the inbox&#39;s actions have tools: <code>triage_cluster</code> sets the status (with a note), assigns, snoozes, quarantines or releases clusters, <code>decide_merge_suggestion</code> decides a merge suggestion, <code>move_tests_to_new_cluster</code> moves tests out of a cluster, <code>rerun_cluster_in_ci</code> re-runs a cluster&#39;s tests in CI, and <code>link_issue</code> and <code>unlink_issue</code> manage tickets.</p><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2>',36)),r(n),e[2]||(e[2]=a('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/mass-failure.html">Triage a run gone red</a>: the clusters, used to collapse a red run into a few causes</li><li><a href="./ai-diagnosis.html">AI diagnosis</a>: an explanation of a cluster against your git diff</li><li><a href="./evidence.html">Failure evidence</a>: everything captured about one execution in the cluster</li><li><a href="/guide/concepts.html#error-fingerprint-failure-cluster">Core concepts</a>: fingerprint and failure cluster</li></ul>',2))])}const q=d(g,[["render",f]]);export{_ as __pageData,q as default};
